// F6.1 rider outfit v1, step 2 (self-made, no assets): procedural helmet, goggles and backpack for Manny.
// Sizes come from Manny's own rest-pose skin (head vertices → ellipsoid, back vertices → pack anchor), so the
// gear fits whatever proportions the model has. Everything is built in a local "gear frame":
// x = rider's left→right side axis (x = y × z), y = up, z = facing (toes at rest).
import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
import type { GearColors } from './outfit';

export type V3 = [number, number, number];

/** Axis-aligned extent of `pts` (xyz-packed, model space) in the gear frame spanned by horizontal facing `fwd`. */
export interface HeadFit { center: V3; radii: V3 }

/** Unit horizontal facing + side axis (x = up × fwd, right-handed with y up). */
export function gearBasis(fwd: V3): { x: V3; y: V3; z: V3 } {
  const l = Math.hypot(fwd[0], fwd[2]) || 1;
  const z: V3 = [fwd[0] / l, 0, fwd[2] / l];
  return { x: [z[2], 0, -z[0]], y: [0, 1, 0], z };
}

/** Bounding ellipsoid of the head vertices, measured along the gear frame (center in model space). */
export function fitHead(pts: ArrayLike<number>, fwd: V3): HeadFit {
  const b = gearBasis(fwd);
  const lo = [Infinity, Infinity, Infinity], hi = [-Infinity, -Infinity, -Infinity];
  for (let i = 0; i + 2 < pts.length; i += 3) {
    const p = [pts[i], pts[i + 1], pts[i + 2]];
    const c = [b.x, b.y, b.z].map((a) => a[0] * p[0] + a[1] * p[1] + a[2] * p[2]);
    for (let k = 0; k < 3; k++) { lo[k] = Math.min(lo[k], c[k]); hi[k] = Math.max(hi[k], c[k]); }
  }
  if (!Number.isFinite(lo[0])) return { center: [0, 0, 0], radii: [0.08, 0.12, 0.1] };
  const m = [0, 1, 2].map((k) => (lo[k] + hi[k]) / 2);
  const center: V3 = [0, 1, 2].map((k) => b.x[k] * m[0] + b.y[k] * m[1] + b.z[k] * m[2]) as V3;
  return { center, radii: [0, 1, 2].map((k) => (hi[k] - lo[k]) / 2) as V3 };
}

/**
 * Where the backpack's front face touches the back: among `pts` between heights `y0`..`y1`, the centre (side / height)
 * and the rearmost point along `fwd`. Returns the model-space contact point.
 */
export function backAnchor(pts: ArrayLike<number>, fwd: V3, y0: number, y1: number): V3 | null {
  const b = gearBasis(fwd);
  let n = 0, sx = 0, minZ = Infinity;
  for (let i = 0; i + 2 < pts.length; i += 3) {
    const y = pts[i + 1];
    if (y < y0 || y > y1) continue;
    const px = b.x[0] * pts[i] + b.x[2] * pts[i + 2], pz = b.z[0] * pts[i] + b.z[2] * pts[i + 2];
    sx += px; n++; minZ = Math.min(minZ, pz);
  }
  if (!n) return null;
  const cx = sx / n, cy = (y0 + y1) / 2;
  return [b.x[0] * cx + b.z[0] * minZ, cy, b.x[2] * cx + b.z[2] * minZ];
}

/** Helmet shell lower-edge height (unit sphere, cos of polar angle) at azimuth φ (0 = front). */
export function helmetRim(phi: number): number {
  // front: just above the goggles (brow), sides over the ears, back down to the nape
  const f = (1 + Math.cos(phi)) / 2; // 1 front … 0 back
  return -0.5 + 0.62 * f * f;
}

export interface GearDims {
  helmetScale: number; // helmet radii = head radii × this
  goggleY: number; // goggle centre, fraction of head ry above head centre
  goggleH: number; // lens height (m)
  strapH: number; // strap height (m)
  pack: V3; // backpack w / h / d (m)
}
export const GEAR_DIMS: GearDims = { helmetScale: 1.13, goggleY: 0.06, goggleH: 0.05, strapH: 0.03, pack: [0.27, 0.36, 0.11] };

/** Open helmet shell (unit-ish sphere scaled to `r`), rim shaped by `helmetRim`, double-sided material expected. */
export function helmetGeometry(r: V3, seg = 24, rings = 10): THREE.BufferGeometry {
  const pos: number[] = [], uv: number[] = [], idx: number[] = [];
  for (let j = 0; j <= rings; j++) {
    for (let i = 0; i <= seg; i++) {
      const phi = (i / seg) * Math.PI * 2;
      const thMax = Math.acos(helmetRim(phi));
      const th = (j / rings) * thMax;
      const s = Math.sin(th);
      // slight crown ridge so it reads as a shell, not a sphere
      const k = 1 + 0.025 * Math.cos(2 * phi) * s;
      pos.push(r[0] * s * Math.sin(phi) * k, r[1] * Math.cos(th), r[2] * s * Math.cos(phi) * k);
      uv.push(i / seg, j / rings);
    }
  }
  for (let j = 0; j < rings; j++) {
    for (let i = 0; i < seg; i++) {
      const a = j * (seg + 1) + i, b = a + seg + 1;
      idx.push(a, b, a + 1, a + 1, b, b + 1);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

/**
 * Strip of an elliptic cylinder (radii rx, rz) from azimuth `a0` to `a1` (0 = front), height `h`, bulged outward by
 * `bulge` at mid-height (goggle lenses are convex).
 */
export function bandGeometry(rx: number, rz: number, h: number, a0: number, a1: number, bulge = 0, seg = 18): THREE.BufferGeometry {
  const pos: number[] = [], idx: number[] = [];
  const rows = bulge ? 3 : 1;
  for (let j = 0; j <= rows; j++) {
    const t = j / rows, y = (t - 0.5) * h, k = 1 + bulge * Math.sin(Math.PI * t);
    for (let i = 0; i <= seg; i++) {
      const a = a0 + ((a1 - a0) * i) / seg;
      pos.push(rx * k * Math.sin(a), y, rz * k * Math.cos(a));
    }
  }
  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < seg; i++) {
      const a = j * (seg + 1) + i, b = a + seg + 1;
      idx.push(a, a + 1, b, a + 1, b + 1, b);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

export interface GearMeshes { head: THREE.Group; back: THREE.Group; materials: Record<keyof GearColors, THREE.MeshStandardMaterial> }

/**
 * Build the gear in model space (rest pose): `head` holds helmet + goggles around `head`, `back` the pack at `back`.
 * Both groups get a matrix in the gear frame; callers re-parent them to bones.
 */
export function buildGear(head: HeadFit, back: V3 | null, fwd: V3, d: GearDims = GEAR_DIMS): GearMeshes {
  const materials = {
    helmet: new THREE.MeshStandardMaterial({ roughness: 0.35, metalness: 0.05, side: THREE.DoubleSide }),
    lens: new THREE.MeshStandardMaterial({ roughness: 0.08, metalness: 0.9 }),
    strap: new THREE.MeshStandardMaterial({ roughness: 0.8, side: THREE.DoubleSide }),
    pack: new THREE.MeshStandardMaterial({ roughness: 0.7 }),
  };
  const b = gearBasis(fwd);
  const frame = (p: V3) => new THREE.Matrix4().makeBasis(v(b.x), v(b.y), v(b.z)).setPosition(p[0], p[1], p[2]);
  const mesh = (g: THREE.BufferGeometry, m: THREE.Material, name: string) => {
    const o = new THREE.Mesh(g, m); o.name = name; o.castShadow = true; return o;
  };
  const r = head.radii, s = d.helmetScale;
  const hr: V3 = [r[0] * s, r[1] * s, r[2] * s];
  const headG = new THREE.Group(); headG.name = 'gear-head';
  headG.matrixAutoUpdate = false;
  headG.matrix.copy(frame(head.center));
  const shell = mesh(helmetGeometry(hr), materials.helmet, 'helmet');
  shell.position.y = r[1] * 0.12; // sit on the crown, not around the chin
  headG.add(shell);
  // goggles: lens across the front, strap around the helmet back, both just outside the helmet's horizontal section
  const gy = r[1] * d.goggleY;
  const sec = (y: number) => Math.sqrt(Math.max(0, 1 - ((y - shell.position.y) / hr[1]) ** 2)); // helmet section at y
  const lensR = Math.max(sec(gy), 0.85) * 1.03;
  const lens = mesh(bandGeometry(r[0] * s * lensR, r[2] * s * lensR, d.goggleH, -1.15, 1.15, 0.06), materials.lens, 'goggle-lens');
  const strap = mesh(bandGeometry(r[0] * s * lensR * 1.01, r[2] * s * lensR * 1.01, d.strapH, 1.1, Math.PI * 2 - 1.1), materials.strap, 'goggle-strap');
  lens.position.y = gy; strap.position.y = gy;
  headG.add(lens, strap);
  const backG = new THREE.Group(); backG.name = 'gear-back';
  backG.matrixAutoUpdate = false;
  if (back) {
    backG.matrix.copy(frame(back));
    const [w, h, dd] = d.pack;
    const pack = mesh(new RoundedBoxGeometry(w, h, dd, 2, 0.035), materials.pack, 'backpack');
    pack.position.z = -dd / 2 + 0.01;
    // a lid / top pocket so it reads as a pack, not a brick
    const lid = mesh(new RoundedBoxGeometry(w * 0.86, h * 0.26, dd * 0.55, 2, 0.025), materials.strap, 'backpack-lid');
    lid.position.set(0, h * 0.28, -dd - 0.005);
    backG.add(pack, lid);
  }
  return { head: headG, back: backG, materials };
}

const v = (a: V3) => new THREE.Vector3(a[0], a[1], a[2]);

/** Apply a colourway to the gear materials (sRGB hex). */
export function paintGear(m: GearMeshes['materials'], c: GearColors) {
  for (const k of Object.keys(m) as (keyof GearColors)[]) m[k].color.set(c[k]);
}
