// H.1 step 3b-2: blend weights for the on-foot locomotion clips (Quaternius UAL, CC0) from the walk.ts ground speed.
// Pure function (unit-tested): piecewise-linear between the clip anchor speeds, weights always sum to 1.
import { WALK } from '../core/walk';

export type LocoClip = 'idle' | 'walk' | 'jog' | 'sprint';
export type LocoWeights = Record<LocoClip, number>;

/** Speed (m/s) at which each clip has full weight. Jog = run speed so a held run is a pure jog; sprint reserved for later. */
export const LOCO_ANCHORS: readonly (readonly [LocoClip, number])[] = [
  ['idle', 0],
  ['walk', WALK.walkSpeed],
  ['jog', WALK.runSpeed],
  ['sprint', 5.5],
];

export function locomotionWeights(speed: number): LocoWeights {
  const a = Math.abs(speed);
  const w: LocoWeights = { idle: 0, walk: 0, jog: 0, sprint: 0 };
  const A = LOCO_ANCHORS;
  if (!(a > A[0][1])) { w[A[0][0]] = 1; return w; }
  for (let i = 1; i < A.length; i++) {
    const [k0, s0] = A[i - 1], [k1, s1] = A[i];
    if (a <= s1) {
      const f = (a - s0) / (s1 - s0);
      w[k0] = 1 - f; w[k1] = f;
      return w;
    }
  }
  w[A[A.length - 1][0]] = 1;
  return w;
}
