// H.1 step 3c-2: procedural wave. The UAL Standard pack has no wave clip (its `Interact` reads as reaching for
// something), so the wave is an arm IK target layered over the Idle clip: the free (left) arm lifts the hand above
// the shoulder, slightly forward and out, and swings it side to side about the elbow. Pure function, unit-tested;
// the renderer (manny.ts) blends from the clip's hand position to this target by the layer weight.

export const WAVE = {
  /** One wave (s); matches EMOTE.oneShot.wave. */
  duration: 2.4,
  /** Lift-in time before the hand starts swinging (s). */
  lift: 0.35,
  /** Side-to-side swings per second. */
  hz: 2.1,
  /** Half swing (m, sideways at the hand). */
  amp: 0.12,
  /** Hand offset from the shoulder at the centre of the swing (m, rider frame: +x = rider's left, +y up, +z forward). */
  hand: [0.36, 0.36, 0.14] as const,
  /** Elbow pole direction (out and down: the elbow points away from the body). */
  pole: [0.55, -0.15, 0.05] as const,
} as const;

export interface WaveTarget { hand: [number, number, number]; pole: [number, number, number] }

const smooth = (x: number) => { const c = Math.min(1, Math.max(0, x)); return c * c * (3 - 2 * c); };

/**
 * Hand / pole offsets from the waving shoulder at layer time `t` (s). `side` = +1 for the left arm, −1 for the right
 * (mirrors x). The swing ramps in after the lift so the hand does not jerk sideways on the way up.
 */
export function waveTarget(t: number, side: 1 | -1 = 1): WaveTarget {
  const ramp = smooth((t - WAVE.lift * 0.5) / WAVE.lift);
  const s = Math.sin(2 * Math.PI * WAVE.hz * Math.max(0, t - WAVE.lift * 0.5)) * WAVE.amp * ramp;
  const [hx, hy, hz] = WAVE.hand, [px, py, pz] = WAVE.pole;
  // swing on an arc about the elbow: a little drop at the ends of the swing
  const drop = (s * s) / (2 * 0.3);
  return { hand: [side * (hx + s), hy - drop, hz], pole: [side * px, py, pz] };
}
