// H.1 step 3b (part 1): runtime retarget core. Copies an animated source skeleton (Quaternius UAL, CC0) onto a
// target skeleton (Manny) whose rest pose differs, using per-bone world-space rotation deltas:
//   tgtWorld = srcWorldNow · srcRestWorld⁻¹ · tgtRestWorld,   tgtLocal = tgtParentWorld⁻¹ · tgtWorld
// Root (hips) translation is copied as a delta from rest, scaled by the hip-height ratio and carried through world space
// (source parent frame → target parent frame), so a Z-up Blender armature drives a Y-up UE skeleton correctly. Unmapped target bones
// in between (e.g. Manny spine_02 / spine_04, twist bones) keep their rest local transform. Pure three.js math,
// no rendering, so it is unit-testable; wiring into MannyRider + AnimationMixer is the next step.
import * as THREE from 'three';

export interface RetargetPair { src: THREE.Object3D; tgt: THREE.Object3D }

const _q = new THREE.Quaternion();
const _qp = new THREE.Quaternion();
const _v = new THREE.Vector3();
const _qs = new THREE.Quaternion();

function worldQuat(o: THREE.Object3D, out: THREE.Quaternion): THREE.Quaternion {
  o.updateWorldMatrix(true, false);
  return o.getWorldQuaternion(out);
}

/** Depth of a node below the root (parents first when sorted ascending). */
function depth(o: THREE.Object3D): number {
  let d = 0;
  for (let p = o.parent; p; p = p.parent) d++;
  return d;
}

export class Retargeter {
  /** Pairs sorted so every target parent is processed before its children. */
  readonly pairs: readonly RetargetPair[];
  private readonly srcRestInv: THREE.Quaternion[];
  private readonly tgtRest: THREE.Quaternion[];
  private readonly rootSrcRest: THREE.Vector3 | null = null;
  private readonly rootTgtRest: THREE.Vector3 | null = null;
  private readonly rootScale: number = 1;

  /**
   * Capture rest poses. Call while both skeletons are in their reference pose (source: A_TPose frame).
   * @param root optional mapped root pair whose local position is retargeted (hips → pelvis)
   * @param heightRatio target hip height / source hip height (scales root translation deltas)
   */
  constructor(pairs: readonly RetargetPair[], root?: RetargetPair, heightRatio = 1) {
    this.pairs = [...pairs].sort((a, b) => depth(a.tgt) - depth(b.tgt));
    this.srcRestInv = this.pairs.map((p) => worldQuat(p.src, new THREE.Quaternion()).invert());
    this.tgtRest = this.pairs.map((p) => worldQuat(p.tgt, new THREE.Quaternion()));
    if (root) {
      this.rootSrcRest = root.src.position.clone();
      this.rootTgtRest = root.tgt.position.clone();
      this.rootScale = heightRatio;
      this.root = root;
    }
  }

  private readonly root: RetargetPair | null = null;

  /** Pose the target from the source's current pose. `weight` 0..1 slerps from the target's current local pose. */
  apply(weight = 1): void {
    const w = Math.min(1, Math.max(0, weight));
    if (w <= 0) return;
    this.pairs[0]?.src.updateWorldMatrix(true, true);
    for (let i = 0; i < this.pairs.length; i++) {
      const { src, tgt } = this.pairs[i];
      src.getWorldQuaternion(_q).multiply(this.srcRestInv[i]).multiply(this.tgtRest[i]);
      if (tgt.parent) {
        tgt.parent.updateWorldMatrix(true, false);
        tgt.parent.getWorldQuaternion(_qp).invert();
        _q.premultiply(_qp);
      }
      if (w >= 1) tgt.quaternion.copy(_q);
      else tgt.quaternion.slerp(_q, w);
      tgt.updateMatrixWorld(true);
    }
    if (this.root && this.rootSrcRest && this.rootTgtRest) {
      // delta in the source parent frame → world → target parent frame (rest-relative, so a shared root transform cancels)
      _v.copy(this.root.src.position).sub(this.rootSrcRest).multiplyScalar(this.rootScale);
      if (this.root.src.parent) _v.applyQuaternion(worldQuat(this.root.src.parent, _qs));
      if (this.root.tgt.parent) _v.applyQuaternion(worldQuat(this.root.tgt.parent, _qs).invert());
      _v.add(this.rootTgtRest);
      this.root.tgt.position.lerp(_v, w);
      this.root.tgt.updateMatrixWorld(true);
    }
  }
}

/** Build pairs from a name map (source name → target node), skipping bones missing on either side. */
export function pairsFromMap(
  srcRoot: THREE.Object3D,
  tgtRoot: THREE.Object3D,
  map: Readonly<Record<string, string>>,
  resolveTarget: (srcName: string, tgtNames: readonly string[]) => string | undefined,
): { pairs: RetargetPair[]; missing: string[] } {
  const tgtNames: string[] = [];
  tgtRoot.traverse((o) => { if (o.name) tgtNames.push(o.name); });
  const pairs: RetargetPair[] = [];
  const missing: string[] = [];
  for (const srcName of Object.keys(map)) {
    const src = srcRoot.getObjectByName(srcName);
    const tName = resolveTarget(srcName, tgtNames);
    const tgt = tName ? tgtRoot.getObjectByName(tName) : undefined;
    if (src && tgt) pairs.push({ src, tgt });
    else missing.push(srcName);
  }
  return { pairs, missing };
}
