// H.1 step 3a: bone mapping from the Quaternius Universal Animation Library rig (Rigify DEF-* names, CC0)
// to the UE5 Manny skeleton used by src/rider/manny.ts. Pure data + lookup; the runtime retarget (rest-pose
// delta per bone in world space) is step 3b. Manny's glTF node names carry a numeric suffix (e.g. "thigh_l_77").

/** UAL bone → Manny bone (base name, without the glTF index suffix). Fingers / twist bones are not retargeted. */
export const UAL_TO_MANNY: Readonly<Record<string, string>> = {
  'DEF-hips': 'pelvis',
  'DEF-spine.001': 'spine_01',
  'DEF-spine.002': 'spine_03',
  'DEF-spine.003': 'spine_05',
  'DEF-neck': 'neck_01',
  'DEF-head': 'head',
  'DEF-shoulder.L': 'clavicle_l',
  'DEF-upper_arm.L': 'upperarm_l',
  'DEF-forearm.L': 'lowerarm_l',
  'DEF-hand.L': 'hand_l',
  'DEF-shoulder.R': 'clavicle_r',
  'DEF-upper_arm.R': 'upperarm_r',
  'DEF-forearm.R': 'lowerarm_r',
  'DEF-hand.R': 'hand_r',
  'DEF-thigh.L': 'thigh_l',
  'DEF-shin.L': 'calf_l',
  'DEF-foot.L': 'foot_l',
  'DEF-toe.L': 'ball_l',
  'DEF-thigh.R': 'thigh_r',
  'DEF-shin.R': 'calf_r',
  'DEF-foot.R': 'foot_r',
  'DEF-toe.R': 'ball_r',
};

/** Clips kept in public/assets/rider/ual-clips.glb (see scripts/extract-ual-clips.mjs). */
export const UAL_CLIPS = {
  restPose: 'A_TPose',
  idle: 'Idle_Loop',
  walk: 'Walk_Loop',
  jog: 'Jog_Fwd_Loop',
  sprint: 'Sprint_Loop',
  sitEnter: 'Sitting_Enter',
  sitIdle: 'Sitting_Idle_Loop',
  sitExit: 'Sitting_Exit',
  dance: 'Dance_Loop',
  talk: 'Idle_Talking_Loop',
  interact: 'Interact',
} as const;

/** "thigh_l_77" → "thigh_l"; names without a numeric suffix are returned unchanged. */
export function mannyBaseName(nodeName: string): string {
  return nodeName.replace(/_\d+$/, '');
}

/** Resolve the Manny node name for a UAL bone given the Manny node names present in the loaded scene. */
export function resolveMannyBone(ualBone: string, mannyNodeNames: readonly string[]): string | undefined {
  const base = UAL_TO_MANNY[ualBone];
  if (!base) return undefined;
  return mannyNodeNames.find((n) => mannyBaseName(n) === base);
}
