// H.1 step 3b-2: plays the Quaternius UAL clips (CC0, public/assets/rider/ual-clips.glb) on a hidden source skeleton
// with an AnimationMixer and copies the result onto Manny through the Retargeter (retarget.ts).
// The hidden skeleton is parented next to Manny under the rider root, so both share the world transform (the
// world-space rest delta cancels it). Locomotion clips are sampled at the walk.ts gait phase (no drift between the
// footstep logic and the animation); idle runs on its own clock.
import * as THREE from 'three';
import { emoteLayerWeights, emoteWeight, type Emote, type EmoteState } from './emote';
import { locomotionWeights, type LocoClip } from './locomotion';
import { pairsFromMap, Retargeter } from './retarget';
import { resolveMannyBone, UAL_CLIPS, UAL_TO_MANNY } from './ual-map';

export interface UalClips { scene: THREE.Object3D; animations: THREE.AnimationClip[] }

/** Bones left to the procedural solver while walking: the arm that carries the board (Manny `_r`, pose arm 1). */
export const CARRY_ARM_UAL = ['DEF-upper_arm.R', 'DEF-forearm.R', 'DEF-hand.R'] as const;

const LOCO: Record<LocoClip, string> = { idle: UAL_CLIPS.idle, walk: UAL_CLIPS.walk, jog: UAL_CLIPS.jog, sprint: UAL_CLIPS.sprint };
/** H.1 step 3c: emote → clip. The wave has no clip (step 3c-2): the body plays Idle and manny.ts lifts the arm by IK
 *  (wave.ts). */
const EMOTES: Partial<Record<Emote, string>> = { dance: UAL_CLIPS.dance, talk: UAL_CLIPS.talk };

export class UalDriver {
  readonly source: THREE.Object3D;
  readonly missing: string[];
  private mixer: THREE.AnimationMixer;
  private actions = new Map<LocoClip, THREE.AnimationAction>();
  private carry: Retargeter;
  /** Board arm only, blended over the procedural carry IK while emoting (board put down). */
  private arm: Retargeter;
  private emotes = new Map<Emote, THREE.AnimationAction>();
  private idleT = 0;

  /**
   * @param clips loaded ual-clips.glb
   * @param manny Manny model root; must be in its rest (bind) pose when this is constructed
   * @param parent node that also holds Manny (rider root)
   */
  constructor(clips: UalClips, manny: THREE.Object3D, parent: THREE.Object3D) {
    this.source = clips.scene;
    this.source.name = 'ual-source';
    this.source.visible = false;
    parent.add(this.source);
    this.mixer = new THREE.AnimationMixer(this.source);
    const clip = (n: string) => {
      const c = clips.animations.find((a) => a.name === n);
      if (!c) throw new Error(`UAL: missing clip ${n}`);
      return c;
    };
    // reference pose: sample A_TPose at t = 0
    const ref = this.mixer.clipAction(clip(UAL_CLIPS.restPose));
    ref.play();
    this.mixer.update(0);
    parent.updateMatrixWorld(true);
    const names: string[] = [];
    manny.traverse((o) => { if (o.name) names.push(o.name); });
    const map = Object.fromEntries(Object.entries(UAL_TO_MANNY).filter(([k]) => !(CARRY_ARM_UAL as readonly string[]).includes(k)));
    const { pairs, missing } = pairsFromMap(this.source, manny, map, resolveMannyBone);
    this.missing = missing;
    const root = pairs.find((p) => p.src.name === 'DEF-hips');
    // hip height above the shared root (both rest models stand with the soles on its origin)
    const h = (o: THREE.Object3D) => parent.worldToLocal(o.getWorldPosition(new THREE.Vector3())).y;
    const ratio = root ? h(root.tgt) / Math.max(1e-3, h(root.src)) : 1;
    this.carry = new Retargeter(pairs, root, ratio);
    const armMap = Object.fromEntries(Object.entries(UAL_TO_MANNY).filter(([k]) => (CARRY_ARM_UAL as readonly string[]).includes(k)));
    this.arm = new Retargeter(pairsFromMap(this.source, manny, armMap, resolveMannyBone).pairs);
    ref.stop();
    for (const k of Object.keys(LOCO) as LocoClip[]) {
      const a = this.mixer.clipAction(clip(LOCO[k]));
      a.play();
      a.setEffectiveWeight(0);
      this.actions.set(k, a);
    }
    for (const k of Object.keys(EMOTES) as Emote[]) {
      const a = this.mixer.clipAction(clip(EMOTES[k]!));
      a.play();
      a.setEffectiveWeight(0);
      this.emotes.set(k, a);
    }
  }

  /**
   * Sample the locomotion blend for `speed` (m/s, < 0 = backwards) at gait `phase` 0..1, layer the emotes on top
   * (locomotion gets 1 − emote weight) and pose Manny (all but the board arm, see `applyArm`).
   */
  walk(dt: number, phase: number, speed: number, emote?: EmoteState) {
    const w = locomotionWeights(speed);
    const e = emote ? emoteWeight(emote) : 0;
    for (const a of this.emotes.values()) a.setEffectiveWeight(0);
    let still = 0; // weight of clip-less emotes (wave): the body stands in Idle under them
    if (emote) for (const l of emoteLayerWeights(emote)) {
      const a = this.emotes.get(l.kind);
      if (!a) { still += l.w; continue; }
      a.time = l.t % a.getClip().duration;
      a.setEffectiveWeight(a.getEffectiveWeight() + l.w);
    }
    const ph = speed < 0 ? 1 - phase : phase;
    for (const [k, a] of this.actions) {
      const d = a.getClip().duration;
      if (k === 'idle') { this.idleT = (this.idleT + dt) % d; a.time = this.idleT; } else a.time = ph * d;
      a.setEffectiveWeight(w[k] * (1 - e) + (k === 'idle' ? still : 0));
    }
    this.mixer.update(0);
    this.carry.apply(1);
  }

  /** Blend the board arm from its procedural pose (already on Manny) to the clip by `w` 0..1. */
  applyArm(w: number) {
    this.arm.apply(w);
  }
}
